<?php if (!$rows): ?><div class="card empty-state"><div class="big"><?= e(__('Aún no hay reseñas')) ?></div><p><?= e(__('Se solicitan automáticamente después de cada cita completada. Tú decides cuáles publicar.')) ?></p></div><?php else: ?>
<?php foreach ($rows as $r): ?><div class="card" style="padding:18px 22px"><div class="card-head" style="margin:0"><div><span style="color:var(--gold-text);letter-spacing:3px"><?= str_repeat('★', (int)$r['rating']) . str_repeat('☆', 5 - (int)$r['rating']) ?></span> <b><?= e($r['client_name']) ?></b> → <?= e($r['prof_name']) ?> <span class="hint"><?= e(fdate($r['created_at'])) ?></span>
  <span class="badge <?= ['approved' => 'badge-ok', 'pending' => 'badge-warn', 'rejected' => 'badge-bad'][$r['status']] ?>"><?= e(['approved' => __('Publicada'), 'pending' => __('Por moderar'), 'rejected' => __('Rechazada')][$r['status']]) ?></span><?php if ($r['comment']): ?><p style="margin:8px 0 0"><?= e($r['comment']) ?></p><?php endif; ?></div>
  <?php if (\Aurea\Core\Auth::role() !== 'professional'): ?><div class="btn-row" style="margin:0"><?php foreach (['approve' => ['Publicar', 'btn-gold'], 'reject' => ['Rechazar', 'btn-line'], 'delete' => ['Eliminar', 'btn-danger']] as $act => [$l, $c]): ?><form class="inline-form" method="post" action="<?= e(url('/admin/resenas/' . $r['id'] . '/accion')) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="<?= $act ?>"><button class="btn <?= $c ?> btn-sm" type="submit"><?= e(__($l)) ?></button></form><?php endforeach; ?></div><?php endif; ?></div></div><?php endforeach; endif; ?>
